// The pcn874 validator, bundled for the browser page (pcn874.html).
//
// The site ships plain ES modules and no bundler, and products/pcn874 is
// TypeScript. The page must run the validator itself - not a port, not a fork
// that can drift - so the bundle is the four modules the validator needs
// (sources, layout, parse, validate) with their types stripped by Node's own
// module.stripTypeScriptTypes in "strip" mode, which replaces type syntax with
// whitespace and changes nothing else. Line N of a source is line N + 4 of its
// bundled file (the 4 are the header).
//
// The generated files are committed under src/vendor/pcn874/ so the page, the
// local server and the tests see them; scripts/bundle-pcn874.js writes them,
// and scripts/build-site.js regenerates them from products/pcn874/src on every
// build and refuses to publish if the committed copy differs. So what ships is
// always what pcn874's own tests ran against.
//
// Build-time only. No shipped page imports this module, so it does not ship.
import * as nodeModule from 'node:module';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

/** In dependency order: each imports only the ones before it. */
export const PCN874_MODULES = Object.freeze(['sources', 'layout', 'parse', 'validate']);

/** products/pcn874/src, from this product's root. */
export const PCN874_SOURCE_DIR = '../pcn874/src';

/** Where the bundle lives inside this product, and so on the site. */
export const PCN874_VENDOR_DIR = 'src/vendor/pcn874';

const HEADER_LINES = 4;

const vendoredPath = (name) => `${PCN874_VENDOR_DIR}/${name}.js`;

/**
 * Node 22 marks stripTypeScriptTypes experimental and says so on stderr the
 * first time it runs. A successful build must write nothing to stderr (the
 * build tests hold it to that), so exactly that one warning is dropped while
 * the bundler runs; every other warning passes through untouched. The strip
 * itself is checked by the result, not trusted: the committed bundle must equal
 * it byte for byte, and tests/pcn874-bundle.test.js runs every pcn874 fixture
 * through both.
 */
function withoutStripWarning(fn) {
  const emit = process.emitWarning;
  process.emitWarning = function (warning, ...rest) {
    const text = typeof warning === 'string' ? warning : warning?.message;
    if (/^stripTypeScriptTypes is an experimental feature/.test(String(text))) return undefined;
    return emit.call(this, warning, ...rest);
  };
  try {
    return fn();
  } finally {
    process.emitWarning = emit;
  }
}
const sha256 = (text) => createHash('sha256').update(text).digest('hex');

function header(name, source) {
  const lines = [
    `// GENERATED by products/il-biz-tools/scripts/bundle-pcn874.js from products/pcn874/src/${name}.ts - do not edit here.`,
    '// Types stripped by Node\'s module.stripTypeScriptTypes (mode "strip"); nothing else is changed,',
    `// so line N of the source is line N+${HEADER_LINES} here. Regenerate: node scripts/bundle-pcn874.js`,
    `// source sha256: ${sha256(source)}`,
  ];
  if (lines.length !== HEADER_LINES) throw new Error('header must stay 4 lines: the line-offset note depends on it');
  return lines.join('\n');
}

/**
 * Bundle the validator from its TypeScript source.
 *
 * @param {(name: string) => string|null|undefined} readSource  text of products/pcn874/src/<name>.ts
 * @returns {{files: {path: string, text: string}[], problems: string[]}}  any problem means no usable bundle
 */
export function bundlePcn874(readSource) {
  const files = [];
  const problems = [];
  const strip = nodeModule.stripTypeScriptTypes;
  if (typeof strip !== 'function') {
    return { files, problems: [`this Node (${process.version}) has no module.stripTypeScriptTypes; the bundle needs Node 22.13 or later`] };
  }
  for (const name of PCN874_MODULES) {
    const source = readSource(name);
    if (typeof source !== 'string') {
      problems.push(`${PCN874_SOURCE_DIR}/${name}.ts cannot be read`);
      continue;
    }
    let body;
    try {
      body = withoutStripWarning(() => strip(source, { mode: 'strip' }));
    } catch (e) {
      problems.push(`${PCN874_SOURCE_DIR}/${name}.ts cannot be type-stripped: ${e.message.split('\n')[0]}`);
      continue;
    }
    for (const m of body.matchAll(/\b(?:import|export)\b[^'";]*?\bfrom\s*(['"])([^'"]+)\1/g)) {
      const spec = m[2];
      if (!PCN874_MODULES.some((other) => spec === `./${other}.js`)) {
        problems.push(`${PCN874_SOURCE_DIR}/${name}.ts imports ${spec}, which is not bundled (${PCN874_MODULES.join(', ')})`);
      }
    }
    files.push({ path: vendoredPath(name), text: `${header(name, source)}\n${body}` });
  }
  return { files: problems.length ? [] : files, problems };
}

/**
 * Everything that makes the committed bundle differ from a fresh one; empty
 * means src/vendor/pcn874/ is exactly what bundling products/pcn874/src gives.
 *
 * @param {{readSource: (name: string) => string|null, readVendored: (path: string) => string|null, listVendored: () => string[]}} access
 * @returns {string[]}
 */
export function bundleProblems({ readSource, readVendored, listVendored }) {
  const { files, problems } = bundlePcn874(readSource);
  if (problems.length) return problems;
  const out = [];
  for (const { path, text } of files) {
    const committed = readVendored(path);
    if (typeof committed !== 'string') out.push(`${path} is missing`);
    else if (committed !== text) out.push(`${path} differs from what products/pcn874/src bundles to today`);
  }
  const expected = new Set(PCN874_MODULES.map((m) => `${m}.js`));
  for (const name of listVendored()) {
    if (!expected.has(name)) out.push(`${PCN874_VENDOR_DIR}/${name} is not generated by the bundler`);
  }
  return out;
}

/** The file-system reads bundleProblems needs, rooted at this product. */
export function fsBundleAccess(root) {
  const read = (path) => (existsSync(path) && statSync(path).isFile() ? readFileSync(path, 'utf8') : null);
  const vendorDir = join(root, PCN874_VENDOR_DIR);
  return {
    readSource: (name) => read(join(root, PCN874_SOURCE_DIR, `${name}.ts`)),
    readVendored: (path) => read(join(root, path)),
    listVendored: () => (existsSync(vendorDir) ? readdirSync(vendorDir).sort() : []),
  };
}
